entries.query:
MATCH (n:AZUser)
WHERE n.userprincipalname CONTAINS '#EXT#' // Entra ID guest user (external UPN pattern)
AND n.enabled = true
AND (
  // never signed in AND created more than 30+ days
  (
    coalesce(n.lastsuccessfulsignindatetime, '') = '' 
    AND n.whencreated < tostring(datetime() - duration('P30D'))
  )

  // OR not signed-in for more than 30+ days
  OR n.lastsuccessfulsignindatetime < tostring(datetime() - duration('P30D'))
)
RETURN n

